# keyword arguments understood by the extxyz reader as the sign convention
# used when converting a stress tensor into a virial tensor
_STRESS_SIGN_OPTIONS = ("stress_sign", "virial_sign", "stress_to_virial_sign")


def _stress_sign_option(**kwargs) -> float:
    """Extract the stress sign convention from a bag of keyword arguments.

    dpdata passes all user keyword arguments down to the format drivers, so
    unrelated arguments are silently ignored here.
    """
    for key in _STRESS_SIGN_OPTIONS:
        if kwargs.get(key, None) is not None:
            return _parse_stress_sign(kwargs[key])
    return _parse_stress_sign(None)

