_STRESS_SIGN_OPTIONS = ("stress_sign", "virial_sign", "stress_to_virial_sign")


def _parse_stress_sign(value) -> float:
    """Normalize the ``stress_sign`` option into a float multiplier.

    Parameters
    ----------
    value : float or str
        Either a number, or one of the aliases ``ase``/``negative``/``minus``
        (equivalent to ``-1``) and ``positive``/``plus`` (equivalent to ``+1``).

    Returns
    -------
    float
        the multiplier ``s`` used in ``virial = s * volume * stress``
    """
    if value is None:
        return -1.0
    if isinstance(value, str):
        key = value.strip().lower()
        if key in _STRESS_SIGN_ALIASES:
            return _STRESS_SIGN_ALIASES[key]
        try:
            return float(key)
        except ValueError as e:
            raise RuntimeError(
                f"unknown stress sign convention {value!r}; use a number or one of "
                f"{sorted(_STRESS_SIGN_ALIASES)}"
            ) from e
    return float(value)


